  hull.addColorStop(0, '#ffffff');
  hull.addColorStop(0.45, PALETTE.hull);
  hull.addColorStop(1, '#7fa6cc');
  ctx.fillStyle = hull;

  ctx.beginPath();
  ctx.moveTo(0, -SHIP.height / 2);
  ctx.lineTo(16, -6);
  ctx.lineTo(SHIP.width / 2, 16);
  ctx.lineTo(SHIP.width / 2 - 6, 26);
  ctx.lineTo(10, 20);
  ctx.lineTo(0, 30);
  ctx.lineTo(-10, 20);
  ctx.lineTo(-SHIP.width / 2 + 6, 26);
  ctx.lineTo(-SHIP.width / 2, 16);
  ctx.lineTo(-16, -6);
